# ==============================================================================
# Helper formatting function
# ==============================================================================
def format_meal(meal_tuple, meal_id, slot_type):
    title, subtitle, image_str, serving, prep, kcal, prot, carbs, fat, cost, ingredients, instructions, tip = meal_tuple
    
    ing_lines = []
    for i, ing in enumerate(ingredients):
        name, portion, ing_cost = ing
        escaped_name = name.replace("'", "\\'")
        escaped_portion = portion.replace("'", "\\'")
        ing_lines.append(f"""          {{
            id: '{meal_id}-i{i+1}',
            name: '{escaped_name}',
            portion: '{escaped_portion}',
            costUsd: {ing_cost:.2f},
          }}""")
    ing_str = ",\n".join(ing_lines)

    inst_lines = []
    for inst in instructions:
        escaped_inst = inst.replace("'", "\\'")
        inst_lines.append(f"          '{escaped_inst}',")
    inst_str = "\n".join(inst_lines)

    escaped_title = title.replace("'", "\\'")
    escaped_sub = subtitle.replace("'", "\\'")
    escaped_serving = serving.replace("'", "\\'")
    escaped_prep = prep.replace("'", "\\'")
    escaped_tip = tip.replace("'", "\\'")

    return f"""      {{
        id: '{meal_id}',
        type: '{slot_type}',
        title: '{escaped_title}',
        subtitle: '{escaped_sub}',
        image: {image_str},
        servingSize: '{escaped_serving}',
        prepTime: '{escaped_prep}',
        baseKcal: {kcal},
        baseProtein: {prot},
        baseCarbs: {carbs},
        baseFat: {fat},
        costUsd: {cost:.2f},
        ingredients: [
{ing_str}
        ],
        instructions: [
{inst_str}
        ],
        budgetTips: '{escaped_tip}',
      }}"""

